insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('spoons-and-refills-week-planner', 'Spoons and Refills Week Planner', 'worksheet'::resource_kind, 'A planner where a client lists what drains and refills their energy across one week.', 'Use it to help a client spread demands and rest more evenly.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through last week day by day and let the client name which tasks cost the most. The point is noticing patterns, not scoring days. Ask what one refill could be protected next week, and keep the plan small enough to actually happen.', '[{"id": "f0", "type": "textarea", "label": "The three things that drained me most last week"}, {"id": "f1", "type": "textarea", "label": "The three things that refilled me"}, {"id": "f2", "type": "textarea", "label": "Which day felt heaviest, and why"}, {"id": "f3", "type": "textarea", "label": "One refill I will protect this week"}, {"id": "f4", "type": "textarea", "label": "One demand I could shrink or move"}, {"id": "f5", "type": "textarea", "label": "Who could help me with something on the list"}]'::jsonb, array['energy', 'planning', 'self-care']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('transition-day-preparation-page', 'Transition Day Preparation Page', 'worksheet'::resource_kind, 'A page for planning the hours before and after a big change of routine or setting.', 'Use it to help a client prepare for a day that breaks their usual routine.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick an upcoming day with a change in it, such as travel, a move or a new job. Have the client plan the morning, the hard middle and the evening wind-down. Check that rest is on the page as much as tasks are.', '[{"id": "f0", "type": "textarea", "label": "What is changing on this day"}, {"id": "f1", "type": "textarea", "label": "What I can prepare the night before"}, {"id": "f2", "type": "textarea", "label": "The part of the day I expect to be hardest"}, {"id": "f3", "type": "textarea", "label": "What I will do to settle myself in that moment"}, {"id": "f4", "type": "textarea", "label": "Who I can message if the day gets heavy"}, {"id": "f5", "type": "textarea", "label": "How I will wind down afterward"}]'::jsonb, array['transitions', 'planning', 'routine']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('compliment-receiving-log', 'Compliment Receiving Log', 'worksheet'::resource_kind, 'A log for catching kind words from others and noting how the client responds to them.', 'Use it to help a client notice and take in kind feedback.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Many clients deflect praise automatically. Ask them to log what was said, what they said back and what they would like to say instead. Review the log together and look for the deflecting habits, with curiosity rather than correction.', '[{"id": "f0", "type": "textarea", "label": "What kind thing someone said to me"}, {"id": "f1", "type": "textarea", "label": "What I said or did in response"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body or thoughts"}, {"id": "f3", "type": "textarea", "label": "What I could say next time instead"}, {"id": "f4", "type": "textarea", "label": "What I think they saw in me"}]'::jsonb, array['appreciation', 'self-worth', 'log']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('boundary-script-builder-sheet', 'Boundary Script Builder Sheet', 'worksheet'::resource_kind, 'A sheet for drafting short, kind and firm words for a limit the client wants to set.', 'Use it to help a client put a boundary into words before the conversation.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose one real situation where the client wants to say no or set a limit. Draft the sentence together, shorten it, and practice saying it aloud in session. Agree on what the client will do if the other person pushes back.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a limit"}, {"id": "f1", "type": "textarea", "label": "What I want and what I do not want"}, {"id": "f2", "type": "textarea", "label": "My boundary in one sentence"}, {"id": "f3", "type": "textarea", "label": "A warmer way to say it and a firmer way"}, {"id": "f4", "type": "textarea", "label": "What the other person might say back"}, {"id": "f5", "type": "textarea", "label": "What I will do if they push on it"}]'::jsonb, array['boundaries', 'assertiveness', 'communication']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('sunday-reset-review-page', 'Sunday Reset Review Page', 'worksheet'::resource_kind, 'A short end-of-week page for looking back at wins, snags and the week ahead.', 'Use it to give a client a steady weekly rhythm of review and planning.', array['Adults', 'Teens']::text[], '15 minutes weekly', 'Keep this light so clients actually use it. Start with what went right before what snagged, and finish with one thing to carry forward. Bring it to session to see how the week looked from the client''s own page.', '[{"id": "f0", "type": "textarea", "label": "Three things that went well this week"}, {"id": "f1", "type": "textarea", "label": "One thing that snagged"}, {"id": "f2", "type": "textarea", "label": "What I learned about myself"}, {"id": "f3", "type": "textarea", "label": "One thing I want to carry into next week"}, {"id": "f4", "type": "textarea", "label": "One thing I can let go of"}]'::jsonb, array['weekly review', 'reflection', 'routine']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('hot-thought-spotlight-record', 'Hot Thought Spotlight Record', 'cbt'::resource_kind, 'A thought record page that begins by picking the single most upsetting thought from a moment.', 'Use it to help a client focus a thought record on the thought that matters most.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients often list many thoughts and lose the thread. Have them rate each one for how strongly it hits and spotlight only the top one. Then look for evidence for and against it and write a more balanced statement in the client''s own words.', '[{"id": "f0", "type": "textarea", "label": "The situation in a sentence"}, {"id": "f1", "type": "textarea", "label": "My thoughts in that moment"}, {"id": "f2", "type": "textarea", "label": "The hot thought, the one that hits hardest"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports it"}, {"id": "f4", "type": "textarea", "label": "Evidence that does not fit it"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought, in my own words"}, {"id": "f6", "type": "textarea", "label": "How strongly I believe the hot thought now"}]'::jsonb, array['thought record', 'automatic thoughts', 'CBT']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('forecast-versus-reality-tracker', 'Forecast Versus Reality Tracker', 'cbt'::resource_kind, 'A tracker where a client writes a prediction before an event and what actually happened after.', 'Use it to help a client compare what they expect with what occurs.', array['Adults', 'Teens']::text[], 'Ten minutes per event, over two weeks', 'Ask for predictions in concrete, checkable terms rather than feelings. Review the tracker in session and look at how often the outcome was different from, or milder than, the prediction. Let the client draw the conclusion.', '[{"id": "f0", "type": "textarea", "label": "The event coming up"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "How sure I am, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What surprised me"}, {"id": "f5", "type": "textarea", "label": "What this tells me about my predictions"}]'::jsonb, array['predictions', 'behavioral experiment', 'anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('rigid-rules-to-preferences-rewrite', 'Rigid Rules to Preferences Rewrite', 'cbt'::resource_kind, 'A sheet for turning rigid "should" rules into flexible preferences.', 'Use it to help a client loosen strict rules they hold about themselves and others.', array['Adults', 'Teens']::text[], '20 minutes', 'List the "shoulds", "musts" and "have tos" the client says in session. Rewrite each as a want, a preference or a choice, and notice how the feeling shifts. Be curious about where each rule came from rather than arguing with it.', '[{"id": "f0", "type": "textarea", "label": "A \"should\" I say to myself often"}, {"id": "f1", "type": "textarea", "label": "Where I think I learned it"}, {"id": "f2", "type": "textarea", "label": "How I feel when I break it"}, {"id": "f3", "type": "textarea", "label": "The same idea as a preference or a choice"}, {"id": "f4", "type": "textarea", "label": "A \"should\" I put on other people"}, {"id": "f5", "type": "textarea", "label": "What might be different if I loosened it"}]'::jsonb, array['distortions', 'self-criticism', 'flexibility']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-timeline', 'Core Belief Evidence Timeline', 'cbt'::resource_kind, 'A timeline of life moments that fit, and moments that do not fit, a belief the client holds about themselves.', 'Use it to help a client see a core belief against the full picture of their life.', array['Adults']::text[], 'Full session', 'Choose a belief the client is ready to look at and keep the focus on everyday evidence, not painful memories. Fill in both sides of the timeline, give the weaker side time, and end with a more balanced sentence the client can live with.', '[{"id": "f0", "type": "textarea", "label": "The belief I am looking at"}, {"id": "f1", "type": "textarea", "label": "Moments that seem to fit it"}, {"id": "f2", "type": "textarea", "label": "Moments that do not fit it"}, {"id": "f3", "type": "textarea", "label": "Who in my life would disagree with it"}, {"id": "f4", "type": "textarea", "label": "A fairer way to say it"}, {"id": "f5", "type": "textarea", "label": "One small action that fits the fairer belief"}]'::jsonb, array['core beliefs', 'evidence', 'timeline']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('worry-time-appointment-card', 'Worry Time Appointment Card', 'cbt'::resource_kind, 'A card for scheduling a daily worry slot and parking worries until then.', 'Use it to help a client contain worry to a set time and place.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Agree on a short fixed time, not too close to bedtime. Between slots the client jots a few words and returns to the task at hand. In the slot, sort items into things to act on and things to let sit, and review how the week went.', '[{"id": "f0", "type": "textarea", "label": "My worry time and place"}, {"id": "f1", "type": "textarea", "label": "Worries I jotted during the day"}, {"id": "f2", "type": "textarea", "label": "Which of them I can act on"}, {"id": "f3", "type": "textarea", "label": "The first small step for each one"}, {"id": "f4", "type": "textarea", "label": "Which I can let sit for now"}, {"id": "f5", "type": "textarea", "label": "How the week with a worry slot went"}]'::jsonb, array['worry', 'containment', 'scheduling']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('values-compass-weekly-check', 'Values Compass Weekly Check', 'act'::resource_kind, 'A weekly check of which valued directions the client moved toward and which they drifted from.', 'Use it to help a client keep their actions pointed at what matters.', array['Adults', 'Teens']::text[], '20 minutes weekly', 'Name three or four values with the client and rate how closely this week matched each, without grading the person. Ask for one action tied to the least visited value. Keep the tone as a compass check, not a report card.', '[{"id": "f0", "type": "textarea", "label": "Values I am steering by"}, {"id": "f1", "type": "textarea", "label": "Which one I moved toward most this week"}, {"id": "f2", "type": "textarea", "label": "Which one I drifted from"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "One small action for the next week"}, {"id": "f5", "type": "textarea", "label": "Who could join me in it"}]'::jsonb, array['values', 'committed action', 'weekly review']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('hands-over-eyes-thought-distance-exercise', 'Hands Over Eyes Thought Distance Exercise', 'act'::resource_kind, 'A guided exercise using hands held to the face to show how thoughts crowd the view.', 'Use it to help a client feel the difference between holding thoughts and being buried by them.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client hold both hands close over their eyes as if they were a hard thought, and describe what they can see. Then move the hands away slowly and notice what comes back into view. Talk through how it felt and what it could mean for daily life.', '[{"id": "f0", "type": "textarea", "label": "The thought I held in my hands"}, {"id": "f1", "type": "textarea", "label": "What I could see with it close"}, {"id": "f2", "type": "textarea", "label": "What I could see with it at arm''s length"}, {"id": "f3", "type": "textarea", "label": "What changed in my body"}, {"id": "f4", "type": "textarea", "label": "Where I could use this in my week"}]'::jsonb, array['defusion', 'cognitive fusion', 'experiential']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('sticky-thought-label-practice', 'Sticky Thought Label Practice', 'act'::resource_kind, 'A practice of adding "I am having the thought that" to a stuck thought and noticing the shift.', 'Use it to help a client step back from a thought without arguing with it.', array['Adults', 'Teens']::text[], '15 minutes', 'Choose a thought that keeps returning. Have the client say it plainly, then with the label, then as "I notice my mind is telling me that". Ask what changed, if anything, and accept a small answer. Practice the label in daily life.', '[{"id": "f0", "type": "textarea", "label": "A thought that keeps sticking to me"}, {"id": "f1", "type": "textarea", "label": "The thought said with the label added"}, {"id": "f2", "type": "textarea", "label": "What I notice when I say it that way"}, {"id": "f3", "type": "textarea", "label": "What my mind is trying to do for me"}, {"id": "f4", "type": "textarea", "label": "What I would do next if the thought were just a thought"}]'::jsonb, array['defusion', 'thoughts', 'mindfulness']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('willingness-volume-knob-page', 'Willingness Volume Knob Page', 'act'::resource_kind, 'A page where the client rates their willingness to feel something in order to do something that matters.', 'Use it to help a client explore willingness as a choice they can turn up or down.', array['Adults', 'Teens']::text[], '20 minutes', 'Name a valued action and the uncomfortable feeling that comes with it. Have the client rate willingness from 0 to 10 and explore what moves the dial a point. Respect low numbers and look for a smaller version of the action.', '[{"id": "f0", "type": "textarea", "label": "A thing that matters to me"}, {"id": "f1", "type": "textarea", "label": "The feeling that comes along with it"}, {"id": "f2", "type": "textarea", "label": "My willingness today, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What would raise it by one point"}, {"id": "f4", "type": "textarea", "label": "A smaller version of the action I could take"}, {"id": "f5", "type": "textarea", "label": "What I would be moving toward"}]'::jsonb, array['willingness', 'values', 'acceptance']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('drifting-leaves-noticing-journal', 'Drifting Leaves Noticing Journal', 'act'::resource_kind, 'A log for a short leaves-on-a-stream practice and what the client noticed each time.', 'Use it to help a client practice letting thoughts pass while staying present.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Lead the first round in session. Clients often judge how well it went, so remind them that noticing a thought carried them away is the practice. Review the log for patterns in when it is easier or harder.', '[{"id": "f0", "type": "textarea", "label": "When and where I practiced"}, {"id": "f1", "type": "textarea", "label": "What kinds of thoughts floated by"}, {"id": "f2", "type": "textarea", "label": "When I got carried off by a thought"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['mindfulness', 'defusion', 'practice']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('half-smile-and-willing-hands-practice-card', 'Half-Smile and Willing Hands Practice Card', 'dbt'::resource_kind, 'A card for pairing a relaxed face and open hands to practice accepting a hard moment.', 'Use it to help a client practice acceptance through the body.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the posture in session: a gentle half-smile, loosened jaw, palms turned up. It is a body cue for willingness, not a way to feel happy. Have the client try it during a mildly hard moment and report back.', '[{"id": "f0", "type": "textarea", "label": "A moment I want to accept"}, {"id": "f1", "type": "textarea", "label": "What my face and hands were doing"}, {"id": "f2", "type": "textarea", "label": "What I did with them instead"}, {"id": "f3", "type": "textarea", "label": "What shifted, even slightly"}, {"id": "f4", "type": "textarea", "label": "Where I will practice this week"}]'::jsonb, array['radical acceptance', 'distress tolerance', 'body-based skills']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('emotion-vulnerability-morning-check', 'Emotion Vulnerability Morning Check', 'dbt'::resource_kind, 'A short morning check of sleep, rest and body state that make strong emotion more likely.', 'Use it to help a client spot the days when emotions will run closer to the surface.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'This is a reflection on vulnerability factors, not a score. Have the client note sleep, meals, movement, medication taken as usual and stressors, then choose one kind step for the day. Review which factors seem to matter most for them.', '[{"id": "f0", "type": "textarea", "label": "How I slept"}, {"id": "f1", "type": "textarea", "label": "What my body needs today"}, {"id": "f2", "type": "textarea", "label": "Stress I am carrying into today"}, {"id": "f3", "type": "textarea", "label": "How close to the surface my feelings are, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "One kind thing I will do for myself today"}, {"id": "f5", "type": "textarea", "label": "How the day went compared with my guess"}]'::jsonb, array['vulnerability factors', 'PLEASE', 'emotion regulation']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-an-urge-sheet', 'Pros and Cons of Acting on an Urge Sheet', 'dbt'::resource_kind, 'A four-box sheet weighing acting on an urge against resisting it, for now and for later.', 'Use it to help a client slow down and see both short and long term effects.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill in the sheet while the client is calm, not in the middle of an urge. Include the real short-term benefits of acting, because leaving them out loses trust. Keep a copy in the client''s phone for the next time an urge shows up.', '[{"id": "f0", "type": "textarea", "label": "The urge I am weighing"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it"}, {"id": "f3", "type": "textarea", "label": "Pros of waiting it out"}, {"id": "f4", "type": "textarea", "label": "Cons of waiting it out"}, {"id": "f5", "type": "textarea", "label": "What I will do first when the urge shows up"}]'::jsonb, array['urges', 'pros and cons', 'distress tolerance']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('both-and-statements-page', 'Both-And Statements Page', 'dbt'::resource_kind, 'A page for rewriting "either or" thoughts as statements that hold two things at once.', 'Use it to help a client practice dialectical thinking.', array['Adults', 'Teens']::text[], '20 minutes', 'Collect a few all-or-nothing statements from recent sessions. Rewrite each with "and" in place of "but", and see what the client feels with both parts allowed. Keep it playful and give them time to find their own wording.', '[{"id": "f0", "type": "textarea", "label": "An either-or thought I had"}, {"id": "f1", "type": "textarea", "label": "The thought with both sides held"}, {"id": "f2", "type": "textarea", "label": "Two things that are both true right now"}, {"id": "f3", "type": "textarea", "label": "Where I see this in my relationships"}, {"id": "f4", "type": "textarea", "label": "How I feel with both sides allowed"}]'::jsonb, array['dialectics', 'middle path', 'cognitive flexibility']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('five-senses-comfort-kit-planner', 'Five Senses Comfort Kit Planner', 'dbt'::resource_kind, 'A page for planning a small kit of items for each of the five senses.', 'Use it to help a client assemble a kit they can reach for when distressed.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through sight, sound, smell, taste and touch and let the client pick items they already like. Some clients prefer a note on their phone to a physical kit. Rehearse using one item in session so it is familiar later.', '[{"id": "f0", "type": "textarea", "label": "Something to look at"}, {"id": "f1", "type": "textarea", "label": "Something to listen to"}, {"id": "f2", "type": "textarea", "label": "A smell I find calming"}, {"id": "f3", "type": "textarea", "label": "Something safe to taste"}, {"id": "f4", "type": "textarea", "label": "Something comforting to touch"}, {"id": "f5", "type": "textarea", "label": "Where I will keep my kit"}]'::jsonb, array['self-soothe', 'five senses', 'distress tolerance']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('couple-check-in-table-agenda', 'Couple Check-In Table Agenda', 'couples'::resource_kind, 'A short agenda for a weekly partner meeting that starts with appreciation and ends with plans.', 'Use it to give partners a steady, low-stakes time to talk about the relationship.', array['Couples']::text[], '30 minutes weekly', 'Introduce it as a routine, not a fix. Each partner shares an appreciation, one thing that went well, then one request for the coming week. Set a time limit and hold to it so the meeting stays safe to repeat.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "What went well between us"}, {"id": "f3", "type": "textarea", "label": "Partner A: one request for next week"}, {"id": "f4", "type": "textarea", "label": "Partner B: one request for next week"}, {"id": "f5", "type": "textarea", "label": "What we agreed on and when we will meet again"}]'::jsonb, array['connection', 'weekly review', 'communication']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('outside-stress-listening-guide-for-two', 'Outside Stress Listening Guide for Two', 'couples'::resource_kind, 'A guide for taking turns listening to each other''s outside stress without fixing it.', 'Use it to help partners support each other about stress that comes from outside the relationship.', array['Couples']::text[], '30 minutes', 'One partner talks about a stress while the other listens, asks questions and shows understanding without giving advice. Then switch. Coach partners on resisting the urge to solve, and ask what each of them needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the stress I am carrying"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I understood and one question I asked"}, {"id": "f2", "type": "textarea", "label": "Partner B: the stress I am carrying"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I understood and one question I asked"}, {"id": "f4", "type": "textarea", "label": "What each of us needed from the other"}, {"id": "f5", "type": "textarea", "label": "What we will do next time"}]'::jsonb, array['listening', 'stress', 'Gottman']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('repair-phrase-menu-for-two', 'Repair Phrase Menu for Two', 'couples'::resource_kind, 'A menu of short phrases partners can use mid-argument to slow things down.', 'Use it to give partners words ready for the moment a talk goes sideways.', array['Couples']::text[], '25 minutes', 'Have each partner pick phrases that feel natural to them, such as "Can we start over?" or "I need a pause". Agree on a signal and on how long a break lasts. Role-play one use in session before sending it home.', '[{"id": "f0", "type": "textarea", "label": "Partner A: phrases I would be willing to say"}, {"id": "f1", "type": "textarea", "label": "Partner B: phrases I would be willing to say"}, {"id": "f2", "type": "textarea", "label": "A signal we agree to use"}, {"id": "f3", "type": "textarea", "label": "How long a pause will be and who restarts"}, {"id": "f4", "type": "textarea", "label": "A time this would have helped us"}]'::jsonb, array['repair', 'conflict', 'de-escalation']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('who-holds-the-plans-fairness-page', 'Who Holds the Plans Fairness Page', 'couples'::resource_kind, 'A check of who plans, remembers and carries the household and family calendar.', 'Use it to help partners talk about the mental load in plain terms.', array['Couples']::text[], '30 minutes', 'Have each partner list tasks that need planning, not only doing, and note who holds each one. Aim for a shared picture, not a tally of blame. Close with one task that changes hands this week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: planning tasks I hold"}, {"id": "f1", "type": "textarea", "label": "Partner B: planning tasks I hold"}, {"id": "f2", "type": "textarea", "label": "Tasks nobody holds yet"}, {"id": "f3", "type": "textarea", "label": "How it feels to hold or not hold them"}, {"id": "f4", "type": "textarea", "label": "One task that changes hands"}, {"id": "f5", "type": "textarea", "label": "How we will check in on it"}]'::jsonb, array['mental load', 'fairness', 'household tasks']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-conversation', 'Dreams Within Conflict Conversation', 'couples'::resource_kind, 'A conversation sheet that asks what hope or story sits underneath a repeated disagreement.', 'Use it to help partners hear the meaning behind a recurring argument.', array['Couples']::text[], '40 minutes', 'Choose one recurring issue. Each partner takes a turn describing what the issue means to them, what it stands for and what they hope for, while the other only asks gentle questions. Do not try to settle it in the session.', '[{"id": "f0", "type": "textarea", "label": "The issue we keep returning to"}, {"id": "f1", "type": "textarea", "label": "Partner A: what it means to me and what I hope for"}, {"id": "f2", "type": "textarea", "label": "Partner B: what it means to me and what I hope for"}, {"id": "f3", "type": "textarea", "label": "What I learned about my partner"}, {"id": "f4", "type": "textarea", "label": "One small thing we could honor from each side"}]'::jsonb, array['gridlock', 'shared meaning', 'Gottman']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('feelings-forecast-window-craft', 'Feelings Forecast Window Craft', 'kids'::resource_kind, 'A paper window the child decorates with the weather of their feelings today.', 'Use it to help a child name a feeling by picking a kind of weather.', array['Children']::text[], '25 minutes', 'The child draws a window frame and fills it with sunshine, rain, wind or storm clouds to match today. Ask what the weather is like and what the sky needs. Ask the parent to hang it up and check the weather together each day. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your window and today''s weather"}, {"id": "f1", "type": "textarea", "label": "What feeling this weather is"}, {"id": "f2", "type": "textarea", "label": "What makes the weather change"}, {"id": "f3", "type": "textarea", "label": "What helps on a stormy day"}, {"id": "f4", "type": "textarea", "label": "Who can I tell about my weather"}]'::jsonb, array['feelings', 'art', 'emotion words']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('calm-down-bottle-building-day', 'Calm-Down Bottle Building Day', 'kids'::resource_kind, 'A craft where a child builds a glitter bottle and uses it as a calm-down tool.', 'Use it to give a child a hands-on way to slow down when upset.', array['Children']::text[], '30 minutes', 'The child fills a clear bottle with water, glue and glitter and watches it settle while breathing slowly. It is a tool to use together, not a punishment or time-out. The parent keeps it within reach and offers it kindly. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What I put in my bottle"}, {"id": "f1", "type": "textarea", "label": "What the glitter looks like when I shake it"}, {"id": "f2", "type": "textarea", "label": "What my breath does as it settles"}, {"id": "f3", "type": "textarea", "label": "When I will use my bottle"}, {"id": "f4", "type": "textarea", "label": "Who will help me use it"}]'::jsonb, array['calming', 'craft', 'self-regulation']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-map', 'Brave Steps Sticker Map', 'kids'::resource_kind, 'A map where a child places a sticker for each small brave step.', 'Use it to help a child see small acts of courage add up.', array['Children']::text[], '25 minutes, then one week at home', 'The child draws a path with stops along the way and names a small brave thing for each stop. The parent gives a sticker for each step tried, whether or not it went perfectly. Keep the steps small and the praise specific. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your path and the stops"}, {"id": "f1", "type": "textarea", "label": "My first brave step"}, {"id": "f2", "type": "textarea", "label": "What I can say to myself when I feel nervous"}, {"id": "f3", "type": "textarea", "label": "Who cheers me on"}, {"id": "f4", "type": "textarea", "label": "What I did that was brave this week"}]'::jsonb, array['courage', 'small steps', 'praise']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('kindness-garden-drawing', 'Kindness Garden Drawing', 'kids'::resource_kind, 'A drawing where each flower in a garden stands for a kind thing done or received.', 'Use it to help a child notice kindness around them and from them.', array['Children']::text[], '25 minutes', 'The child draws flowers and writes or tells one kind act on each petal. Ask which ones were from them and which were for them. The parent adds a flower every week for a kind thing they notice. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your garden"}, {"id": "f1", "type": "textarea", "label": "A kind thing I did"}, {"id": "f2", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f3", "type": "textarea", "label": "A kind thing I could do tomorrow"}, {"id": "f4", "type": "textarea", "label": "How kindness feels in my body"}]'::jsonb, array['kindness', 'art', 'strengths']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('superpower-shield-craft', 'Superpower Shield Craft', 'kids'::resource_kind, 'A shield the child draws or builds, with sections for their strengths and helpers.', 'Use it to help a child describe what makes them strong.', array['Children']::text[], '30 minutes', 'Split a paper shield into four parts: something I am good at, someone who helps me, something I do when it is hard, and a word I like about myself. Tell the parent to add one strength they see at home. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Something I am good at"}, {"id": "f1", "type": "textarea", "label": "Someone who helps me"}, {"id": "f2", "type": "textarea", "label": "What I do when things are hard"}, {"id": "f3", "type": "textarea", "label": "A word I like about myself"}, {"id": "f4", "type": "textarea", "label": "A strength my grown-up sees in me"}]'::jsonb, array['strengths', 'craft', 'confidence']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('both-sides-debate-cards', 'Both Sides Debate Cards', 'game'::resource_kind, 'A card game where players argue a light topic from each side and then try to find the middle.', 'Use it to practice flexible thinking in a group.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Deal topic cards such as "Mornings are better than nights". Players argue one side for one minute, then the other. Turns rotate clockwise. Debrief: what was easier to argue, what did it feel like to hold the other side, and where could this help in real life?', '[{"id": "f0", "type": "textarea", "label": "The topic I argued"}, {"id": "f1", "type": "textarea", "label": "What it felt like to argue the other side"}, {"id": "f2", "type": "textarea", "label": "What I learned about the other view"}, {"id": "f3", "type": "textarea", "label": "A real situation where seeing both sides helps"}]'::jsonb, array['perspective taking', 'flexibility', 'group']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('skill-spinner-wheel-game', 'Skill Spinner Wheel Game', 'game'::resource_kind, 'A wheel game where each spin lands on a coping skill to describe, demonstrate or teach.', 'Use it to review coping skills in a lively way.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make a wheel with skills the group already knows. Players spin in turn and either explain the skill, demonstrate it or give an example of when it helps. A skill can be passed once per player. Debrief on which skills people want to try this week.', '[{"id": "f0", "type": "textarea", "label": "The skill I landed on"}, {"id": "f1", "type": "textarea", "label": "How I would use it"}, {"id": "f2", "type": "textarea", "label": "A time it could help me this week"}, {"id": "f3", "type": "textarea", "label": "A skill I want to try after hearing the others"}]'::jsonb, array['skills', 'coping skills', 'game']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('two-facts-and-a-value-guessing-game', 'Two Facts and a Value Guessing Game', 'game'::resource_kind, 'A round where players share two true facts and one value, and others guess which is the value.', 'Use it to help a group get to know each other through what matters to them.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player writes two facts about themselves and one value they hold, in any order. Others guess which is the value, then ask one question. Turns go around the circle. Debrief: what did you learn about someone, and what values did people share?', '[{"id": "f0", "type": "textarea", "label": "My two facts and my value"}, {"id": "f1", "type": "textarea", "label": "What I learned about someone else"}, {"id": "f2", "type": "textarea", "label": "A value I share with someone here"}, {"id": "f3", "type": "textarea", "label": "How I could act on my value this week"}]'::jsonb, array['values', 'icebreaker', 'group']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('thought-detective-clue-game', 'Thought Detective Clue Game', 'game'::resource_kind, 'A game where teams act as detectives to find clues for and against a thought on a card.', 'Use it to practice checking thoughts against the facts.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Read a thought card aloud. Teams take turns naming a clue that fits it and a clue that does not. Keep a running tally on the board and award a point for each fair clue. Debrief: how did it feel to look for both kinds, and which thoughts in your life deserve this?', '[{"id": "f0", "type": "textarea", "label": "The thought card we worked on"}, {"id": "f1", "type": "textarea", "label": "A clue for it and a clue against it"}, {"id": "f2", "type": "textarea", "label": "What we decided was most fair"}, {"id": "f3", "type": "textarea", "label": "A thought of mine I want to check"}]'::jsonb, array['thoughts', 'evidence', 'game']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('pass-the-strength-ball-circle', 'Pass the Strength Ball Circle', 'game'::resource_kind, 'A circle game where a ball is passed and the catcher names a strength of the thrower.', 'Use it to help a group notice and name each other''s strengths.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players stand or sit in a circle. The thrower names a strength of the catcher, and the catcher thanks them and throws to someone else. Rule: everyone gets the ball once before anyone gets it twice. Debrief on what it felt like to hear and to say it.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone else"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use this week"}]'::jsonb, array['strengths', 'group', 'kindness']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('safety-anchors-inventory-page', 'Safety Anchors Inventory Page', 'worksheet'::resource_kind, 'A page for listing places, objects and people that bring a sense of safety right now.', 'Use it to help a client build a list of safety anchors in the present.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep the focus on the present and on what is safe today, not on past events. Let the client choose real or imagined places. Do not ask for details of what happened. Rehearse picturing one item in session and check that it feels settling.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel safest"}, {"id": "f1", "type": "textarea", "label": "A person who helps me feel safe"}, {"id": "f2", "type": "textarea", "label": "An object that reminds me I am safe"}, {"id": "f3", "type": "textarea", "label": "What my body notices when I think of it"}, {"id": "f4", "type": "textarea", "label": "Where I can find a safety anchor this week"}]'::jsonb, array['grounding', 'safety', 'stabilizing', 'PTSD and trauma']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('present-day-cue-versus-then-sheet', 'Present-Day Cue Versus Then Sheet', 'cbt'::resource_kind, 'A sheet for sorting a reaction into what is happening now and what the body is remembering.', 'Use it to help a client tell today apart from the past when a reminder shows up.', array['Adults']::text[], '20 minutes', 'Work only with the present-day cue and the client''s reaction; no need to describe the past event. Have the client name the date, place and who is with them now. This is a grounding aid you can use in the room, and the pace is the client''s.', '[{"id": "f0", "type": "textarea", "label": "What reminded me"}, {"id": "f1", "type": "textarea", "label": "What my body did"}, {"id": "f2", "type": "textarea", "label": "What the date, place and people are today"}, {"id": "f3", "type": "textarea", "label": "What is different now from then"}, {"id": "f4", "type": "textarea", "label": "What I can say to myself to stay here"}]'::jsonb, array['hypervigilance', 'orienting', 'grounding', 'PTSD and trauma']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('anchor-and-compass-page', 'Anchor and Compass Page', 'act'::resource_kind, 'A page pairing a way to anchor in the body with a direction the client wants to move toward.', 'Use it to help a client stay present with discomfort while still moving toward what matters.', array['Adults']::text[], '25 minutes', 'Begin with the anchor: feet on the floor, slow breath or noticing the room. Then ask about a value and one small step. Keep it brief and stop if the client feels flooded; the anchor comes first.', '[{"id": "f0", "type": "textarea", "label": "My anchor in the body"}, {"id": "f1", "type": "textarea", "label": "What I notice around me right now"}, {"id": "f2", "type": "textarea", "label": "A thing I care about"}, {"id": "f3", "type": "textarea", "label": "One small step I could take toward it"}, {"id": "f4", "type": "textarea", "label": "What would help me carry on if it gets hard"}]'::jsonb, array['values', 'grounding', 'pacing', 'PTSD and trauma']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-card-for-surges', 'TIPP Skills Practice Card for Surges', 'dbt'::resource_kind, 'A card for walking through temperature, intense movement, paced breathing and muscle relaxation.', 'Use it to give a client a body-first option when distress rises quickly.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice each step when the client is calm so it is familiar. Check for any health reasons to adjust the temperature or movement steps before sending it home. If the client feels unsafe, use your own safety plan and share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Which of the four steps I tried"}, {"id": "f1", "type": "textarea", "label": "What it did to my body"}, {"id": "f2", "type": "textarea", "label": "What I would use first in a surge"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card"}, {"id": "f4", "type": "textarea", "label": "Who I can contact if I do not feel safe, and 988 (call or text)"}]'::jsonb, array['TIPP', 'distress tolerance', 'stabilizing', 'PTSD and trauma']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('partner-grounding-plan-for-a-hard-day', 'Partner Grounding Plan for a Hard Day', 'couples'::resource_kind, 'A plan where each partner says what helps and what does not on a day full of reminders.', 'Use it to help partners support each other without asking for details of the past.', array['Couples']::text[], '30 minutes', 'One partner names what helps when a reminder hits, such as space, a hand to hold or a quiet room. The other describes what they can offer. Agree to never press for details. Practice one scenario in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me and what does not"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer and what I will not do"}, {"id": "f2", "type": "textarea", "label": "A signal we both understand"}, {"id": "f3", "type": "textarea", "label": "What we do afterward to reconnect"}, {"id": "f4", "type": "textarea", "label": "What we will try this week"}]'::jsonb, array['safety', 'support', 'pacing', 'PTSD and trauma']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('worry-cloud-popping-craft', 'Worry Cloud Popping Craft', 'kids'::resource_kind, 'A craft where a child draws worries on paper clouds and pops or moves them.', 'Use it to help a child put worries outside themselves and talk about them.', array['Children']::text[], '25 minutes', 'The child draws or tells a worry on each cloud and picks a way to let it go, such as stuffing it in a box or blowing it away. Tell the parent to listen without fixing. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw a worry cloud"}, {"id": "f1", "type": "textarea", "label": "What the worry says"}, {"id": "f2", "type": "textarea", "label": "What I can do when the cloud shows up"}, {"id": "f3", "type": "textarea", "label": "Who can help me with it"}, {"id": "f4", "type": "textarea", "label": "What a calmer sky looks like"}]'::jsonb, array['worry', 'craft', 'externalizing', 'anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('probably-possibly-pretty-sure-game', 'Probably, Possibly, Pretty Sure Game', 'game'::resource_kind, 'A game where players sort worry predictions into how likely they really are.', 'Use it to practice thinking about how likely a feared outcome is.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Write predictions on cards. Players take turns placing a card on a line from "not likely" to "very likely" and defend the spot. Others may move a card once. Debrief on how it felt to place the worries and which ones moved.', '[{"id": "f0", "type": "textarea", "label": "A prediction I placed"}, {"id": "f1", "type": "textarea", "label": "Where I put it and why"}, {"id": "f2", "type": "textarea", "label": "What the group thought"}, {"id": "f3", "type": "textarea", "label": "A worry I want to check this week"}]'::jsonb, array['predictions', 'uncertainty', 'game', 'anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('avoidance-ledger-page', 'Avoidance Ledger Page', 'worksheet'::resource_kind, 'A ledger of what a client avoided, what it saved them and what it cost.', 'Use it to help a client see the full price of avoiding.', array['Adults', 'Teens']::text[], '25 minutes', 'List avoided situations from the past week and note the relief in the short run and the cost in the long run. Look for patterns rather than blame. Choose one entry to approach in a small way.', '[{"id": "f0", "type": "textarea", "label": "Something I avoided"}, {"id": "f1", "type": "textarea", "label": "What I felt as relief"}, {"id": "f2", "type": "textarea", "label": "What it cost me"}, {"id": "f3", "type": "textarea", "label": "What I would like instead"}, {"id": "f4", "type": "textarea", "label": "A small step toward it"}]'::jsonb, array['avoidance', 'anxiety', 'tracking']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('not-knowing-experiment-planner', 'Not Knowing Experiment Planner', 'cbt'::resource_kind, 'A planner for testing how it feels to act without checking or getting certainty.', 'Use it to help a client practice tolerating not knowing.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a moment where the client usually seeks certainty. Plan one experiment, predict the outcome and rate the distress. After the experiment compare the prediction with what happened. Keep it small and repeatable.', '[{"id": "f0", "type": "textarea", "label": "The situation where I want certainty"}, {"id": "f1", "type": "textarea", "label": "My experiment"}, {"id": "f2", "type": "textarea", "label": "My prediction"}, {"id": "f3", "type": "textarea", "label": "How distressed I expect to be, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I learned"}]'::jsonb, array['uncertainty', 'behavioral experiment', 'anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('worry-as-weather-practice-page', 'Worry as Weather Practice Page', 'act'::resource_kind, 'A page for noticing worries as passing weather while carrying on with valued tasks.', 'Use it to help a client let worry be present while acting on what matters.', array['Adults', 'Teens']::text[], '20 minutes', 'Offer the weather image: worry comes and goes, and the day can still go on. Have the client name the weather today, a task that matters and how they can do it with the weather present. Check what they tried at the next session.', '[{"id": "f0", "type": "textarea", "label": "Today''s worry weather"}, {"id": "f1", "type": "textarea", "label": "What the worry says"}, {"id": "f2", "type": "textarea", "label": "A task that matters to me today"}, {"id": "f3", "type": "textarea", "label": "How I can do it with the weather there"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['worry', 'defusion', 'values', 'anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-low-mood-page', 'Opposite Action for Low Mood Page', 'dbt'::resource_kind, 'A page for spotting the urge to withdraw and picking an opposite action.', 'Use it to help a client try a small step opposite to what low mood asks for.', array['Adults', 'Teens']::text[], '25 minutes', 'Help the client name what the mood urges, such as staying in bed, then choose a small opposite action. Keep it very small and tied to something they value. If the client mentions thoughts of ending their life, stop and use your safety plan together, and share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "What my low mood is urging me to do"}, {"id": "f1", "type": "textarea", "label": "What the opposite action would be"}, {"id": "f2", "type": "textarea", "label": "A very small version of it"}, {"id": "f3", "type": "textarea", "label": "When I will do it"}, {"id": "f4", "type": "textarea", "label": "What happened afterward"}, {"id": "f5", "type": "textarea", "label": "Who I can reach, and 988 (call or text), if things feel unsafe"}]'::jsonb, array['opposite action', 'low mood', 'behavioral activation', 'depression']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('heavy-day-partner-talk-page', 'Heavy Day Partner Talk Page', 'couples'::resource_kind, 'A short check-in where partners say what a heavy day looks like and what support helps.', 'Use it to help partners support each other through low-energy stretches.', array['Couples']::text[], '30 minutes', 'One partner describes what low days look like, the other what they notice and feel. Agree on what helps and what pushes away. Be clear that support is not fixing. Pick one small shared activity for the week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a heavy day looks like"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I notice and how I feel"}, {"id": "f2", "type": "textarea", "label": "What helps and what does not"}, {"id": "f3", "type": "textarea", "label": "One small thing we could do together"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['support', 'low mood', 'communication', 'depression']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('feelings-color-wheel-craft', 'Feelings Color Wheel Craft', 'kids'::resource_kind, 'A color wheel the child fills in to show how big each feeling is today.', 'Use it to help a child show feelings through color and size.', array['Children']::text[], '25 minutes', 'The child picks colors for feelings such as sad, mad, glad and tired and fills a wheel in the proportions they feel today. Ask about the biggest slice. Tell the parent to look at the wheel with the child each evening. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "My wheel today"}, {"id": "f1", "type": "textarea", "label": "The biggest color and what it is"}, {"id": "f2", "type": "textarea", "label": "What helps this feeling"}, {"id": "f3", "type": "textarea", "label": "Who I can show my wheel to"}, {"id": "f4", "type": "textarea", "label": "What I would like more of"}]'::jsonb, array['feelings', 'art', 'emotion identification', 'depression']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('tiny-wins-bingo', 'Tiny Wins Bingo', 'game'::resource_kind, 'A bingo card of very small daily actions, with a prize for each line.', 'Use it to make small actions feel doable and shareable.', array['Teens', 'Adults', 'Groups']::text[], 'Session game, then a week of play', 'Fill a bingo grid with tiny tasks such as opening the blinds, a short walk or texting a friend. Players mark squares as they do them and share at the next round. Rules: no comparing, every square counts. Debrief on which ones were easiest.', '[{"id": "f0", "type": "textarea", "label": "Squares I marked this week"}, {"id": "f1", "type": "textarea", "label": "Which was easiest"}, {"id": "f2", "type": "textarea", "label": "Which was hardest"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my mood after"}]'::jsonb, array['activity', 'small steps', 'game', 'depression']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('energy-ladder-for-low-days', 'Energy Ladder for Low Days', 'worksheet'::resource_kind, 'A ladder of tasks from tiny to bigger, so a client can pick one rung that fits today''s energy.', 'Use it to help a client match action to energy instead of all or nothing.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the ladder with the client: bottom rungs take under two minutes, top rungs take longer. On a low day aim for one rung up from where they are. Praise any step, and look at the ladder together at each session.', '[{"id": "f0", "type": "textarea", "label": "The smallest things on my ladder"}, {"id": "f1", "type": "textarea", "label": "Some middle rungs"}, {"id": "f2", "type": "textarea", "label": "Some top rungs"}, {"id": "f3", "type": "textarea", "label": "The rung I am on today"}, {"id": "f4", "type": "textarea", "label": "What gets me one rung up"}, {"id": "f5", "type": "textarea", "label": "Who could help me"}]'::jsonb, array['activity scheduling', 'energy', 'depression']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('task-start-countdown-plan', 'Task Start Countdown Plan', 'cbt'::resource_kind, 'A plan that breaks starting a task into a countdown and a first two-minute step.', 'Use it to help a client get past the stuck point of starting.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one task the client keeps putting off. Define the first physical action, a two-minute version and a countdown cue. Plan what they will do if they drift. Review what worked and what did not.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The first physical action"}, {"id": "f2", "type": "textarea", "label": "The two-minute version"}, {"id": "f3", "type": "textarea", "label": "My countdown cue"}, {"id": "f4", "type": "textarea", "label": "What I will do if I drift"}, {"id": "f5", "type": "textarea", "label": "What I will do after as a reward"}]'::jsonb, array['task initiation', 'procrastination', 'executive skills', 'ADHD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('valued-focus-anchor-page', 'Valued Focus Anchor Page', 'act'::resource_kind, 'A page that ties a task to something the client cares about, to help attention stay with it.', 'Use it to help a client connect effort to meaning when attention wanders.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a task that feels dull and ask what it connects to. Write the link on a card the client sees while working. Add a plan for noticing drift and returning without self-criticism.', '[{"id": "f0", "type": "textarea", "label": "The task in front of me"}, {"id": "f1", "type": "textarea", "label": "What it connects to that I care about"}, {"id": "f2", "type": "textarea", "label": "What distracts me most"}, {"id": "f3", "type": "textarea", "label": "How I will notice I drifted"}, {"id": "f4", "type": "textarea", "label": "How I will come back kindly"}]'::jsonb, array['values', 'attention', 'committed action', 'ADHD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('pause-before-reacting-impulse-card', 'Pause Before Reacting Impulse Card', 'dbt'::resource_kind, 'A card for picking a pause, a breath and an alternative before acting on an impulse.', 'Use it to help a client put a short gap between an impulse and an action.', array['Adults', 'Teens']::text[], '15 minutes', 'Identify a common impulse such as interrupting or buying on the spot. Plan a visible cue, a pause of ten seconds and a different action. Role-play one use in session and set up a way to track how many times it worked.', '[{"id": "f0", "type": "textarea", "label": "An impulse I want to slow down"}, {"id": "f1", "type": "textarea", "label": "My cue that tells me to pause"}, {"id": "f2", "type": "textarea", "label": "What I will do in the pause"}, {"id": "f3", "type": "textarea", "label": "The action I would like to take instead"}, {"id": "f4", "type": "textarea", "label": "How it went this week"}]'::jsonb, array['impulse control', 'pause', 'self-regulation', 'ADHD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('reminder-system-agreement-for-two', 'Reminder System Agreement for Two', 'couples'::resource_kind, 'An agreement where partners decide how reminders are given and received without nagging.', 'Use it to help partners cut down on reminder conflict.', array['Couples']::text[], '30 minutes', 'The partner who forgets says what kind of reminder helps. The other says what they can give without feeling like a parent. Agree on a tool such as a shared list or a text, and a way to pause the system if it gets heated.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I like to be reminded"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer and what wears me down"}, {"id": "f2", "type": "textarea", "label": "The tool or signal we will use"}, {"id": "f3", "type": "textarea", "label": "What we do when a reminder goes wrong"}, {"id": "f4", "type": "textarea", "label": "When we will review how it is going"}]'::jsonb, array['reminders', 'communication', 'household tasks', 'ADHD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('my-brain-remote-control-craft', 'My Brain Remote Control Craft', 'kids'::resource_kind, 'A craft where a child builds a remote with buttons for pause, slow, focus and play.', 'Use it to help a child talk about how their attention works and what helps.', array['Children']::text[], '30 minutes', 'The child decorates a paper remote and labels each button with something that helps, such as pause, slow down or one thing at a time. Show the parent how to use the button names as friendly cues at home. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your remote"}, {"id": "f1", "type": "textarea", "label": "What my pause button does"}, {"id": "f2", "type": "textarea", "label": "What my focus button does"}, {"id": "f3", "type": "textarea", "label": "When I need the slow button"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can say to press a button"}]'::jsonb, array['attention', 'craft', 'self-regulation', 'ADHD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('urge-surfing-cards-game', 'Urge Surfing Cards Game', 'game'::resource_kind, 'A card game where players practice naming and riding out urges with set steps.', 'Use it to practice responding to urges in a group.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards with situations that bring up urges. A player draws one, names the urge and picks a skill from a list. Others add ideas. Rules: no stories of use, only skills. Debrief on which skills people want to use this week.', '[{"id": "f0", "type": "textarea", "label": "The situation I drew"}, {"id": "f1", "type": "textarea", "label": "The urge and where I feel it"}, {"id": "f2", "type": "textarea", "label": "The skill I chose"}, {"id": "f3", "type": "textarea", "label": "A skill I got from someone else"}]'::jsonb, array['urges', 'substance use', 'game', 'addiction']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('substance-use-trigger-map', 'Substance Use Trigger Map', 'worksheet'::resource_kind, 'A map of people, places, feelings and times that go with urges.', 'Use it to help a client see where urges cluster and plan around them.', array['Adults', 'Teens']::text[], '25 minutes', 'Use neutral language such as "substance use" and "urges". Have the client map triggers in four categories and star the ones that come up most. Plan one change for each starred trigger and revisit often.', '[{"id": "f0", "type": "textarea", "label": "People or places that go with urges"}, {"id": "f1", "type": "textarea", "label": "Feelings that go with urges"}, {"id": "f2", "type": "textarea", "label": "Times of day that are harder"}, {"id": "f3", "type": "textarea", "label": "The trigger I will plan for first"}, {"id": "f4", "type": "textarea", "label": "What I will do instead"}, {"id": "f5", "type": "textarea", "label": "Who I can call"}]'::jsonb, array['triggers', 'relapse prevention', 'substance use', 'addiction']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('urge-thought-challenge-record', 'Urge Thought Challenge Record', 'cbt'::resource_kind, 'A record for catching the thought that comes with an urge and weighing it.', 'Use it to help a client slow down the thinking that supports an urge.', array['Adults', 'Teens']::text[], '25 minutes', 'Look at what the mind says during an urge, such as "just this once". Record the thought, evidence and a different response. Do not argue with the urge itself; focus on what the client will do in the next ten minutes.', '[{"id": "f0", "type": "textarea", "label": "The urge and the situation"}, {"id": "f1", "type": "textarea", "label": "The thought that came with it"}, {"id": "f2", "type": "textarea", "label": "How much I believed it"}, {"id": "f3", "type": "textarea", "label": "What I know that does not fit it"}, {"id": "f4", "type": "textarea", "label": "What I did instead"}, {"id": "f5", "type": "textarea", "label": "How I felt after"}]'::jsonb, array['urges', 'automatic thoughts', 'substance use', 'addiction']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('values-and-urges-crossroads-page', 'Values and Urges Crossroads Page', 'act'::resource_kind, 'A page showing the road toward values and the road toward an urge, side by side.', 'Use it to help a client see the choice at an urge and what each path means.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw two paths. On one list what an urge offers and what it costs; on the other the values the client wants to live by. Ask what a small step on the second path looks like today. Avoid moralizing.', '[{"id": "f0", "type": "textarea", "label": "What an urge offers me"}, {"id": "f1", "type": "textarea", "label": "What it costs me"}, {"id": "f2", "type": "textarea", "label": "A value I want to live by"}, {"id": "f3", "type": "textarea", "label": "A small step on that path today"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself at the crossroads"}]'::jsonb, array['values', 'urges', 'choice point', 'addiction']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('urge-length-skill-menu', 'Urge Length Skill Menu', 'dbt'::resource_kind, 'A menu of distress tolerance skills sorted by how long an urge lasts.', 'Use it to give a client a ready list of what to do for five, fifteen or sixty minutes.', array['Adults', 'Teens']::text[], '25 minutes', 'Divide the menu into short, medium and long skills such as cold water, a walk and calling someone. Have the client mark favorites and test one in session. Revisit what worked in the next meeting.', '[{"id": "f0", "type": "textarea", "label": "What I can do in five minutes"}, {"id": "f1", "type": "textarea", "label": "What I can do in fifteen minutes"}, {"id": "f2", "type": "textarea", "label": "What I can do in an hour"}, {"id": "f3", "type": "textarea", "label": "The skill I will try first"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to"}]'::jsonb, array['distress tolerance', 'urges', 'skills', 'addiction']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('time-out-and-return-agreement', 'Time-Out and Return Agreement', 'couples'::resource_kind, 'An agreement for taking a break during anger and coming back to the talk.', 'Use it to help partners pause heated moments and return calmly.', array['Couples']::text[], '30 minutes', 'Agree on a word that calls a break, how long it lasts and who returns first. Include what each partner does during the break so it is not read as leaving. Practice calling it once in session while calm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: our break word and what I do in the break"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do in the break"}, {"id": "f2", "type": "textarea", "label": "How long we wait before returning"}, {"id": "f3", "type": "textarea", "label": "Who starts the return and how"}, {"id": "f4", "type": "textarea", "label": "What we will say when we return"}]'::jsonb, array['de-escalation', 'conflict', 'repair', 'anger management']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('volcano-feelings-craft', 'Volcano Feelings Craft', 'kids'::resource_kind, 'A craft where a child builds a volcano and labels the steps before it erupts.', 'Use it to help a child notice the early signs of anger and what to do.', array['Children']::text[], '30 minutes', 'The child draws a volcano and labels steps from simmer to blow. Ask what the body feels at each step and what helps. Tell the parent to use the picture to point out the early steps at home. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your volcano"}, {"id": "f1", "type": "textarea", "label": "What I feel before it erupts"}, {"id": "f2", "type": "textarea", "label": "What my body does"}, {"id": "f3", "type": "textarea", "label": "What helps me cool down"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can do to help"}]'::jsonb, array['anger', 'early warning', 'craft', 'anger management']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('anger-ladder-charades-game', 'Anger Ladder Charades Game', 'game'::resource_kind, 'A game acting out steps from mild irritation to full anger and what to do at each.', 'Use it to help a group see the early steps of anger.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Players draw a step on the ladder and act it out without words while others guess. Then they add one skill for that step. Turns go around. Debrief on early signs people notice in themselves.', '[{"id": "f0", "type": "textarea", "label": "The step I acted"}, {"id": "f1", "type": "textarea", "label": "The sign I notice first in my body"}, {"id": "f2", "type": "textarea", "label": "A skill I would use at that step"}, {"id": "f3", "type": "textarea", "label": "A step I want to catch earlier"}]'::jsonb, array['anger', 'early warning', 'game', 'anger management']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('anger-trigger-and-underneath-feeling-page', 'Anger Trigger and Underneath Feeling Page', 'worksheet'::resource_kind, 'A page that looks for the hurt, fear or worry sitting underneath anger.', 'Use it to help a client name the feeling beneath anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Take a recent anger episode. Ask what was going on before it, what the anger protected and what might be underneath. Never rush the client toward an answer. Ask what they would need in that moment.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What my anger said"}, {"id": "f2", "type": "textarea", "label": "What might be underneath it"}, {"id": "f3", "type": "textarea", "label": "What I needed in that moment"}, {"id": "f4", "type": "textarea", "label": "What I could do differently next time"}]'::jsonb, array['anger', 'emotions', 'triggers', 'anger management']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('hostile-thought-check-record', 'Hostile Thought Check Record', 'cbt'::resource_kind, 'A record for catching thoughts that fuel anger and finding a fairer reading.', 'Use it to help a client loosen quick assumptions about others'' intentions.', array['Adults', 'Teens']::text[], '25 minutes', 'Use a recent upsetting moment and list what the client assumed about the other person. Weigh other explanations and note how anger shifts. Aim for a plausible alternative, not a forced positive one.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I assumed about their intent"}, {"id": "f2", "type": "textarea", "label": "Other possible reasons"}, {"id": "f3", "type": "textarea", "label": "How angry I felt, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "How angry I feel with another view"}, {"id": "f5", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['automatic thoughts', 'interpretation', 'anger', 'anger management']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('unwelcome-thoughts-welcome-mat-page', 'Unwelcome Thoughts Welcome Mat Page', 'act'::resource_kind, 'A page for allowing intrusive thoughts to be present while doing what matters.', 'Use it to help a client respond to intrusive thoughts without a ritual.', array['Adults', 'Teens']::text[], '25 minutes', 'Introduce the idea that fighting the thought makes it louder. Have the client name the thought, notice it and choose a valued action instead of a ritual. Pair it with the exposure work you already do together.', '[{"id": "f0", "type": "textarea", "label": "An unwelcome thought I had"}, {"id": "f1", "type": "textarea", "label": "What I usually do in response"}, {"id": "f2", "type": "textarea", "label": "What I could do instead"}, {"id": "f3", "type": "textarea", "label": "What matters to me right now"}, {"id": "f4", "type": "textarea", "label": "How it felt to let it be there"}]'::jsonb, array['intrusive thoughts', 'defusion', 'response prevention', 'OCD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('wise-mind-check-for-doubt-page', 'Wise Mind Check for Doubt Page', 'dbt'::resource_kind, 'A page for asking what wise mind says when doubt demands more checking.', 'Use it to help a client tell doubt from what they know.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through a moment of doubt. Separate emotion mind (it must be checked), reasonable mind (facts) and wise mind (what I know, and how to live with not knowing). Practice in session with a real example.', '[{"id": "f0", "type": "textarea", "label": "The doubt I had"}, {"id": "f1", "type": "textarea", "label": "What emotion mind said"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind said"}, {"id": "f3", "type": "textarea", "label": "What wise mind says"}, {"id": "f4", "type": "textarea", "label": "What I will do instead of checking"}]'::jsonb, array['wise mind', 'uncertainty', 'compulsions', 'OCD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('reassurance-boundaries-for-partners', 'Reassurance Boundaries for Partners', 'couples'::resource_kind, 'A plan where partners agree how to respond when asked for reassurance.', 'Use it to help partners respond kindly without feeding the cycle.', array['Couples']::text[], '30 minutes', 'The partner who asks and the partner who answers agree on a warm, short reply they can give. Include what the asker will do with the feeling instead. Practice the reply in session. Check in on how it is going.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I tend to ask for"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I have been responding"}, {"id": "f2", "type": "textarea", "label": "A warm reply we agree on"}, {"id": "f3", "type": "textarea", "label": "What Partner A will do with the feeling"}, {"id": "f4", "type": "textarea", "label": "How we will review it"}]'::jsonb, array['reassurance seeking', 'accommodation', 'communication', 'OCD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('bossy-worry-voice-drawing', 'Bossy Worry Voice Drawing', 'kids'::resource_kind, 'A drawing where a child gives a name and face to the bossy worry voice and draws talking back.', 'Use it to help a child separate themselves from the worry voice.', array['Children']::text[], '25 minutes', 'The child names the voice, draws it and writes what it says. Then they draw themselves talking back or saying "no thanks". Show the parent how to use the name at home and avoid giving in. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the bossy voice"}, {"id": "f1", "type": "textarea", "label": "What it says"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "What I would rather do instead"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can help"}]'::jsonb, array['externalizing', 'compulsions', 'drawing', 'OCD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('resist-the-ritual-challenge-cards', 'Resist the Ritual Challenge Cards', 'game'::resource_kind, 'A card game with small challenges that practice waiting before a ritual.', 'Use it to practice delay and willingness in a safe setting.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Cards invite players to practice waiting, such as sitting with a small itch for a minute. Play is voluntary and players can pass. Debrief on what it felt like to wait and what helped. Keep real exposure work in individual sessions.', '[{"id": "f0", "type": "textarea", "label": "The challenge I picked"}, {"id": "f1", "type": "textarea", "label": "How long I waited"}, {"id": "f2", "type": "textarea", "label": "What I felt as I waited"}, {"id": "f3", "type": "textarea", "label": "What helped"}]'::jsonb, array['response delay', 'rituals', 'game', 'OCD']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('panic-first-aid-card', 'Panic First Aid Card', 'worksheet'::resource_kind, 'A pocket card with what to remember and do in the first minute of a panic wave.', 'Use it to give a client a short plan for the start of panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the card with the client in their own words. Include a body fact, a breathing step and an action. Rehearse in session and keep it in a spot they can reach. Revise it after each real use.', '[{"id": "f0", "type": "textarea", "label": "What I tell myself first"}, {"id": "f1", "type": "textarea", "label": "My breathing step"}, {"id": "f2", "type": "textarea", "label": "What I do with my body"}, {"id": "f3", "type": "textarea", "label": "Who I can contact"}, {"id": "f4", "type": "textarea", "label": "What I will do after it passes"}]'::jsonb, array['panic', 'breathing', 'quick reference', 'panic attacks']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('catastrophic-interpretation-check-page', 'Catastrophic Interpretation Check Page', 'cbt'::resource_kind, 'A page for finding the scary meaning given to a body sensation and weighing other explanations.', 'Use it to help a client reconsider what a sensation means.', array['Adults', 'Teens']::text[], '25 minutes', 'Take a sensation like a racing heart. Write the scary meaning, what else could explain it and what has happened before. Rule out medical concerns with the client''s physician as you see fit. Close with a calmer statement.', '[{"id": "f0", "type": "textarea", "label": "The sensation I noticed"}, {"id": "f1", "type": "textarea", "label": "What I feared it meant"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations"}, {"id": "f3", "type": "textarea", "label": "What has happened in the past"}, {"id": "f4", "type": "textarea", "label": "A calmer statement I can say"}]'::jsonb, array['body sensations', 'catastrophizing', 'interpretation', 'panic attacks']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('sensation-willingness-practice-page', 'Sensation Willingness Practice Page', 'act'::resource_kind, 'A practice of allowing a sensation to be there while doing something valued.', 'Use it to help a client make room for body sensations.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a mild sensation and invite the client to notice it with curiosity for a minute while continuing a task. Build up slowly. Ask what mattered enough to keep going. Pair with your exposure plan.', '[{"id": "f0", "type": "textarea", "label": "The sensation I noticed"}, {"id": "f1", "type": "textarea", "label": "Where it lived in my body"}, {"id": "f2", "type": "textarea", "label": "What I did with it"}, {"id": "f3", "type": "textarea", "label": "What mattered enough to keep going"}, {"id": "f4", "type": "textarea", "label": "What I want to try next"}]'::jsonb, array['willingness', 'interoceptive', 'acceptance', 'panic attacks']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('slow-exhale-and-cool-water-plan', 'Slow Exhale and Cool Water Plan', 'dbt'::resource_kind, 'A plan pairing slow paced breathing with cold water on the face.', 'Use it to give a client two body-based steps for a rising wave.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach slow exhales longer than inhales and a splash of cool water. Ask the client to check with their physician if they have a heart condition before using cold. Practice both in session and set a time to use them.', '[{"id": "f0", "type": "textarea", "label": "How my breathing felt"}, {"id": "f1", "type": "textarea", "label": "How the cool water felt"}, {"id": "f2", "type": "textarea", "label": "Which one helped more"}, {"id": "f3", "type": "textarea", "label": "When I will use them"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself"}]'::jsonb, array['TIPP', 'breathing', 'distress tolerance', 'panic attacks']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('partner-support-script-for-a-panic-wave', 'Partner Support Script for a Panic Wave', 'couples'::resource_kind, 'A script of what the partner says and does when panic shows up.', 'Use it to help partners agree on helpful words and actions.', array['Couples']::text[], '30 minutes', 'Have the person who panics say what helps. Have the partner write short lines they can use, such as "I am here, we can wait". Agree on what to avoid saying. Practice in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps in a wave"}, {"id": "f1", "type": "textarea", "label": "Partner B: words I can say"}, {"id": "f2", "type": "textarea", "label": "What to avoid saying"}, {"id": "f3", "type": "textarea", "label": "What we do afterward"}, {"id": "f4", "type": "textarea", "label": "How we will use this next time"}]'::jsonb, array['panic attacks', 'support', 'communication']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('our-family-rules-poster-craft', 'Our Family Rules Poster Craft', 'kids'::resource_kind, 'A poster the child and parent decorate with a few family rules and their reasons.', 'Use it to help a family agree on clear, kind rules.', array['Children']::text[], '30 minutes', 'The child and parent pick three to five rules, phrase them as what to do, and decorate them together. Coach the parent to ask the child for ideas and to refer to the poster calmly. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Our rules"}, {"id": "f1", "type": "textarea", "label": "Why each one matters"}, {"id": "f2", "type": "textarea", "label": "What happens when a rule is forgotten"}, {"id": "f3", "type": "textarea", "label": "What the grown-up will do when it is followed"}, {"id": "f4", "type": "textarea", "label": "Draw our family poster"}]'::jsonb, array['rules', 'family', 'craft', 'parenting']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('catch-them-being-good-game', 'Catch Them Being Good Game', 'game'::resource_kind, 'A game where family members spot and call out helpful actions to earn points for a shared reward.', 'Use it to help parents practice noticing what goes well.', array['Adults', 'Groups']::text[], '25 minutes', 'Players take turns naming something kind or helpful they noticed in someone else and earn a point for the family goal. Rules: only positives, be specific. Debrief on what it felt like to be noticed.', '[{"id": "f0", "type": "textarea", "label": "A good thing I noticed"}, {"id": "f1", "type": "textarea", "label": "Who did it"}, {"id": "f2", "type": "textarea", "label": "What I said"}, {"id": "f3", "type": "textarea", "label": "What it was like to be noticed"}]'::jsonb, array['praise', 'family', 'game', 'parenting']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('calm-parent-pause-plan', 'Calm Parent Pause Plan', 'worksheet'::resource_kind, 'A plan for what a parent does in the minute before reacting to a child''s behavior.', 'Use it to help a parent plan a pause to respond rather than react.', array['Adults']::text[], '25 minutes', 'Identify the moments when the parent feels pulled to react. Plan a cue, a breath and a short script. Normalize that parents have limits. Review what happened after a week.', '[{"id": "f0", "type": "textarea", "label": "Moments that test me"}, {"id": "f1", "type": "textarea", "label": "What I feel in my body first"}, {"id": "f2", "type": "textarea", "label": "My pause and breath"}, {"id": "f3", "type": "textarea", "label": "What I will say or do"}, {"id": "f4", "type": "textarea", "label": "What I can do to repair if I react"}]'::jsonb, array['pause', 'self-regulation', 'parenting']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('harsh-parent-thought-rewrite-sheet', 'Harsh Parent Thought Rewrite Sheet', 'cbt'::resource_kind, 'A sheet for catching harsh thoughts about oneself or the child and rewriting them.', 'Use it to help a parent loosen harsh judgments in tough moments.', array['Adults']::text[], '25 minutes', 'Collect thoughts like "I am failing" or "they do this to upset me". Look at the evidence and write a fairer line the parent can hold. Keep the tone warm.', '[{"id": "f0", "type": "textarea", "label": "A hard parenting moment"}, {"id": "f1", "type": "textarea", "label": "The thought that came"}, {"id": "f2", "type": "textarea", "label": "How much I believed it"}, {"id": "f3", "type": "textarea", "label": "A fairer view"}, {"id": "f4", "type": "textarea", "label": "What I will do next time"}]'::jsonb, array['automatic thoughts', 'self-criticism', 'parent coaching', 'parenting']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('parent-i-want-to-be-compass-page', 'Parent I Want to Be Compass Page', 'act'::resource_kind, 'A page where a parent writes what kind of parent they want to be and one action this week.', 'Use it to help a parent connect daily choices to their values.', array['Adults']::text[], '25 minutes', 'Ask what the parent wants their child to remember about them. Name two or three values and one small action each. Keep the goals small and kind and revisit often.', '[{"id": "f0", "type": "textarea", "label": "What I want my child to remember"}, {"id": "f1", "type": "textarea", "label": "Values I want to act on"}, {"id": "f2", "type": "textarea", "label": "One action for this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will be kind to myself when I miss it"}]'::jsonb, array['values', 'parenting', 'committed action']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('rest-and-care-plan-for-the-new-baby-weeks', 'Rest and Care Plan for the New Baby Weeks', 'dbt'::resource_kind, 'A plan applying self-care skills to sleep, food and support in the new baby weeks.', 'Use it to help a parent protect basic needs during a hard stretch.', array['Adults']::text[], '25 minutes', 'Ask who can take which task and when. Plan a block of rest and a time to eat. Notice any feelings of hopelessness or thoughts of harm and, if present, address them together with your safety plan and 988 (call or text). Keep the plan small.', '[{"id": "f0", "type": "textarea", "label": "What I need most right now"}, {"id": "f1", "type": "textarea", "label": "Who can help and with what"}, {"id": "f2", "type": "textarea", "label": "My rest plan"}, {"id": "f3", "type": "textarea", "label": "My plan to eat and drink"}, {"id": "f4", "type": "textarea", "label": "Who to contact and 988 (call or text) if I feel unsafe"}]'::jsonb, array['PLEASE', 'new parents', 'self-care', 'perinatal and postpartum']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('night-waking-sharing-plan', 'Night Waking Sharing Plan', 'couples'::resource_kind, 'A plan for dividing night waking and daytime care between partners.', 'Use it to help partners share baby care and rest more evenly.', array['Couples']::text[], '30 minutes', 'Each partner lists what they do now and what they need. Draft a plan for nights and days that gives each partner a protected block of rest. Agree on a review date.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I do and what I need"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do and what I need"}, {"id": "f2", "type": "textarea", "label": "Our night plan"}, {"id": "f3", "type": "textarea", "label": "Our day plan"}, {"id": "f4", "type": "textarea", "label": "When we will review it"}]'::jsonb, array['new parents', 'teamwork', 'fairness', 'perinatal and postpartum']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('baby-is-coming-big-sibling-book', 'Baby Is Coming Big Sibling Book', 'kids'::resource_kind, 'A drawn booklet where an older child shows their jobs and feelings about the new baby.', 'Use it to help a child talk about a new sibling.', array['Children']::text[], '30 minutes', 'The child draws pages such as "My feelings", "My job" and "What I like to do with Mom or Dad". Tell the parent to plan one-on-one time. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw how you feel about the baby"}, {"id": "f1", "type": "textarea", "label": "My job as big sibling"}, {"id": "f2", "type": "textarea", "label": "Something I miss"}, {"id": "f3", "type": "textarea", "label": "Something I like"}, {"id": "f4", "type": "textarea", "label": "What I want to do with my grown-up"}]'::jsonb, array['siblings', 'sibling adjustment', 'art', 'perinatal and postpartum']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('support-circle-planning-game', 'Support Circle Planning Game', 'game'::resource_kind, 'A game where players place helpers around a baby and name the job each can do.', 'Use it to help new parents map their help.', array['Adults', 'Groups']::text[], '25 minutes', 'Draw circles around a baby. Players write names or roles of helpers and the job each could take. Turns go around. Rule: no job is too small. Debrief on gaps and who to ask.', '[{"id": "f0", "type": "textarea", "label": "Who I put in my circle"}, {"id": "f1", "type": "textarea", "label": "Jobs they could do"}, {"id": "f2", "type": "textarea", "label": "A gap I noticed"}, {"id": "f3", "type": "textarea", "label": "Who I will ask first"}]'::jsonb, array['support network', 'resources', 'new parents', 'perinatal and postpartum']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('mood-and-sleep-daily-log-for-new-parents', 'Mood and Sleep Daily Log for New Parents', 'worksheet'::resource_kind, 'A log tracking mood, sleep blocks and a bright spot each day.', 'Use it to give a parent and clinician a shared picture of the week.', array['Adults']::text[], 'Five minutes daily for two weeks', 'The log is an aid for conversation. Review patterns together, not scores. If there are thoughts of harm, address them in session and share 988 (call or text). Praise any entries.', '[{"id": "f0", "type": "textarea", "label": "How I slept"}, {"id": "f1", "type": "textarea", "label": "My mood today"}, {"id": "f2", "type": "textarea", "label": "A bright spot"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "What help I need"}, {"id": "f5", "type": "textarea", "label": "988 (call or text) if I feel unsafe"}]'::jsonb, array['mood tracking', 'sleep', 'perinatal and postpartum']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('self-worth-evidence-folder-page', 'Self-Worth Evidence Folder Page', 'cbt'::resource_kind, 'A page for collecting everyday evidence that contradicts a harsh view of oneself.', 'Use it to help a client build a fairer picture of their worth.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for small, concrete evidence such as keeping a promise or helping a friend. Add a line each day. At review time look for what the client tends to discount and gently point it out.', '[{"id": "f0", "type": "textarea", "label": "The harsh thing I say about myself"}, {"id": "f1", "type": "textarea", "label": "Evidence from this week that does not fit it"}, {"id": "f2", "type": "textarea", "label": "What others have noticed in me"}, {"id": "f3", "type": "textarea", "label": "A fairer statement about me"}, {"id": "f4", "type": "textarea", "label": "What I will add to the folder tomorrow"}]'::jsonb, array['evidence', 'self-worth', 'self-criticism', 'self-esteem']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('self-as-story-observing-page', 'Self-as-Story Observing Page', 'act'::resource_kind, 'A page for noticing the story the client tells about themselves and who is telling it.', 'Use it to help a client hold their self-story more lightly.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the story in a few lines, then read it aloud as "my mind tells the story that". Ask what part of them notices the story. Explore what a valued action could look like without needing the story to change first.', '[{"id": "f0", "type": "textarea", "label": "The story I tell about myself"}, {"id": "f1", "type": "textarea", "label": "How it sounds when I add \"my mind tells the story that\""}, {"id": "f2", "type": "textarea", "label": "The part of me that notices the story"}, {"id": "f3", "type": "textarea", "label": "A value I want to act on anyway"}, {"id": "f4", "type": "textarea", "label": "One small action this week"}]'::jsonb, array['self-as-context', 'self-story', 'values', 'self-esteem']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('validate-yourself-practice-page', 'Validate Yourself Practice Page', 'dbt'::resource_kind, 'A page for writing a validating line to oneself in place of a harsh one.', 'Use it to help a client practice self-validation.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose an emotional moment and have the client write what a kind friend would say that is true to the situation. Validation is not agreement with every thought; it is saying that the feeling makes sense. Practice aloud.', '[{"id": "f0", "type": "textarea", "label": "The moment"}, {"id": "f1", "type": "textarea", "label": "What I felt"}, {"id": "f2", "type": "textarea", "label": "What makes sense about that feeling"}, {"id": "f3", "type": "textarea", "label": "A validating sentence to myself"}, {"id": "f4", "type": "textarea", "label": "How it felt to say it"}]'::jsonb, array['self-validation', 'validation', 'emotion regulation', 'self-esteem']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('strengths-i-see-in-you-exchange', 'Strengths I See in You Exchange', 'couples'::resource_kind, 'An exchange where partners share strengths they see in each other and in themselves.', 'Use it to help partners build each other''s sense of worth.', array['Couples']::text[], '25 minutes', 'Partners take turns naming strengths with a specific example, and the receiver says thanks without deflecting. Notice what is hard to hear. Repeat weekly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a strength I see in you, with an example"}, {"id": "f1", "type": "textarea", "label": "Partner B: a strength I see in you, with an example"}, {"id": "f2", "type": "textarea", "label": "What was hard to hear"}, {"id": "f3", "type": "textarea", "label": "A strength I want to claim in myself"}, {"id": "f4", "type": "textarea", "label": "What we will do this week"}]'::jsonb, array['appreciation', 'strengths', 'connection', 'self-esteem']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('strengths-tree-craft', 'Strengths Tree Craft', 'kids'::resource_kind, 'A tree where each leaf is something the child is good at or likes about themselves.', 'Use it to help a child list strengths in a picture.', array['Children']::text[], '30 minutes', 'The child draws a trunk and adds leaves, each with a strength, such as being kind or trying again. Ask what the grown-up would add. Tell the parent to add a leaf each week. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the tree and leaves"}, {"id": "f1", "type": "textarea", "label": "Something I am good at"}, {"id": "f2", "type": "textarea", "label": "Something I like about me"}, {"id": "f3", "type": "textarea", "label": "A time I tried again"}, {"id": "f4", "type": "textarea", "label": "A leaf my grown-up would add"}]'::jsonb, array['strengths', 'craft', 'confidence', 'self-esteem']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('small-hello-challenge-card-game', 'Small Hello Challenge Card Game', 'game'::resource_kind, 'A card game of low-pressure social challenges, played in a group or by a client.', 'Use it to practice small social steps in a safe setting.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Cards offer small steps such as asking someone a question or sharing a favorite song. Players pick a card they can manage, try it with the group and pass if they need to. Debrief on what happened versus what they expected.', '[{"id": "f0", "type": "textarea", "label": "The card I picked"}, {"id": "f1", "type": "textarea", "label": "What I expected to happen"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What I want to try next"}]'::jsonb, array['social skills', 'exposure', 'game', 'social anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('conversation-starter-pocket-page', 'Conversation Starter Pocket Page', 'worksheet'::resource_kind, 'A page of questions and ways to keep a talk going.', 'Use it to give a client ready topics and follow-ups.', array['Teens', 'Adults']::text[], '20 minutes', 'Build the list with the client based on situations they face, such as a party or a work lunch. Include follow-up questions and ways to exit gracefully. Rehearse one in session.', '[{"id": "f0", "type": "textarea", "label": "Places where I need conversation"}, {"id": "f1", "type": "textarea", "label": "Questions I could ask"}, {"id": "f2", "type": "textarea", "label": "Follow-ups I could use"}, {"id": "f3", "type": "textarea", "label": "A graceful way to end a talk"}, {"id": "f4", "type": "textarea", "label": "One I will try this week"}]'::jsonb, array['conversation', 'small talk', 'social anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('post-event-replay-check-sheet', 'Post-Event Replay Check Sheet', 'cbt'::resource_kind, 'A sheet for reviewing a social event fairly rather than replaying only the flaws.', 'Use it to help a client stop harsh after-the-fact replays.', array['Adults', 'Teens']::text[], '25 minutes', 'After an event, ask the client what went well, what was neutral and what they judged. Compare the replay with what others could actually see. Keep the focus on a balanced summary.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "What I remember most"}, {"id": "f2", "type": "textarea", "label": "What went well or was neutral"}, {"id": "f3", "type": "textarea", "label": "What others could actually see"}, {"id": "f4", "type": "textarea", "label": "A fair summary of how it went"}]'::jsonb, array['post-event processing', 'rumination', 'social anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('nervous-but-present-values-page', 'Nervous but Present Values Page', 'act'::resource_kind, 'A page for choosing a social action that matters and doing it with nerves present.', 'Use it to help a client act on a social value while feeling nervous.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what connection or contribution matters to the client. Pick one social action tied to it and expect nerves. Plan how to carry the nerves along rather than waiting for them to leave.', '[{"id": "f0", "type": "textarea", "label": "A relationship or activity I care about"}, {"id": "f1", "type": "textarea", "label": "A social step toward it"}, {"id": "f2", "type": "textarea", "label": "The nerves I expect"}, {"id": "f3", "type": "textarea", "label": "How I will carry them with me"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['values', 'courage', 'committed action', 'social anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('interpersonal-rehearsal-with-dear-man', 'Interpersonal Rehearsal With DEAR MAN', 'dbt'::resource_kind, 'A rehearsal sheet for asking for something from another person using DEAR MAN.', 'Use it to practice an assertive request before a real conversation.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose a request such as asking a coworker to change plans. Write each part of DEAR MAN, then role-play it with you and swap roles. Ask what the client would change.', '[{"id": "f0", "type": "textarea", "label": "The request I want to make"}, {"id": "f1", "type": "textarea", "label": "Describe and express"}, {"id": "f2", "type": "textarea", "label": "Assert and reinforce"}, {"id": "f3", "type": "textarea", "label": "Mindful and appear confident"}, {"id": "f4", "type": "textarea", "label": "Negotiate"}, {"id": "f5", "type": "textarea", "label": "How the role play went"}]'::jsonb, array['DEAR MAN', 'assertiveness', 'interpersonal effectiveness', 'social anxiety']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('grieving-differently-together-page', 'Grieving Differently Together Page', 'couples'::resource_kind, 'A page where partners describe how each grieves and what support they need.', 'Use it to help partners understand different ways of grieving.', array['Couples']::text[], '30 minutes', 'Partners often grieve at different speeds and in different ways. Have each describe what helps, what hurts and what they would like from the other. Avoid judging one style as better.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve and what helps"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve and what helps"}, {"id": "f2", "type": "textarea", "label": "What I would like from my partner"}, {"id": "f3", "type": "textarea", "label": "What I appreciate about how they cope"}, {"id": "f4", "type": "textarea", "label": "One thing we can do together"}]'::jsonb, array['grief', 'support', 'connection', 'grief and loss']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('remembering-box-building-craft', 'Remembering Box Building Craft', 'kids'::resource_kind, 'A box the child decorates and fills with drawings and small objects to remember someone.', 'Use it to help a child remember a loved one in a safe way.', array['Children']::text[], '30 minutes', 'The child decorates a box and chooses items that remind them of the person. Tell the parent to look at it together from time to time and to answer questions simply. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your memory box"}, {"id": "f1", "type": "textarea", "label": "What I put inside"}, {"id": "f2", "type": "textarea", "label": "A favorite thing about the person"}, {"id": "f3", "type": "textarea", "label": "What I miss"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to when I miss them"}]'::jsonb, array['remembrance', 'craft', 'continuing bonds', 'grief and loss']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('stories-we-carry-circle-game', 'Stories We Carry Circle Game', 'game'::resource_kind, 'A circle game where members share a short memory using a prompt card.', 'Use it to help a group share memories and listen to each other.', array['Adults', 'Groups']::text[], '30 minutes', 'Pass a card with a prompt such as "a thing they always said". Each player shares if they want, or passes. Rule: no advice, only listening. Debrief on what it felt like to share and to listen.', '[{"id": "f0", "type": "textarea", "label": "The prompt I picked"}, {"id": "f1", "type": "textarea", "label": "A memory I shared"}, {"id": "f2", "type": "textarea", "label": "What it was like to listen to others"}, {"id": "f3", "type": "textarea", "label": "What I want to carry from today"}]'::jsonb, array['memories', 'remembrance', 'group', 'grief and loss']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('hard-date-honoring-plan', 'Hard Date Honoring Plan', 'worksheet'::resource_kind, 'A plan for days that bring grief back, such as birthdays and holidays.', 'Use it to help a client prepare for a hard date.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose the date and plan the morning, midday and evening. Include something to honor the person, something to care for oneself and someone to be with. Revisit after the date.', '[{"id": "f0", "type": "textarea", "label": "The date and why it is hard"}, {"id": "f1", "type": "textarea", "label": "How I want to honor the person"}, {"id": "f2", "type": "textarea", "label": "How I will care for myself"}, {"id": "f3", "type": "textarea", "label": "Who I would like to be with"}, {"id": "f4", "type": "textarea", "label": "What I will do if it gets heavy"}, {"id": "f5", "type": "textarea", "label": "How it went"}]'::jsonb, array['anniversary reactions', 'planning', 'grief and loss']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('should-have-thoughts-sheet', 'Should Have Thoughts Sheet', 'cbt'::resource_kind, 'A sheet for looking at "I should have" thoughts after a loss and weighing them.', 'Use it to help a client look kindly at guilt in grief.', array['Adults']::text[], '25 minutes', 'Write the "should have" thought, then what the client knew at the time, what they did out of care and what a friend would say. The aim is perspective, not removing the pain. Go at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "The thought I keep having"}, {"id": "f1", "type": "textarea", "label": "What I knew then"}, {"id": "f2", "type": "textarea", "label": "What I did out of care"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f4", "type": "textarea", "label": "A kinder sentence I can hold"}]'::jsonb, array['guilt', 'self-blame', 'grief', 'grief and loss']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('values-in-our-relationship-page', 'Values in Our Relationship Page', 'act'::resource_kind, 'A page for naming what the client wants to bring to their relationship and one step.', 'Use it to help a client act on values rather than on frustration.', array['Adults']::text[], '25 minutes', 'Ask what kind of partner or friend the client wants to be, apart from what the other does. Identify one step this week. Notice when frustration pulls the other way and what a values-led choice might be.', '[{"id": "f0", "type": "textarea", "label": "What kind of partner I want to be"}, {"id": "f1", "type": "textarea", "label": "What I do when I am frustrated"}, {"id": "f2", "type": "textarea", "label": "A values-led step this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will notice and return to it"}]'::jsonb, array['values', 'relationships', 'committed action', 'relationship issues']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('give-skills-practice-page', 'GIVE Skills Practice Page', 'dbt'::resource_kind, 'A page for planning to use gentle, interested, validating and easy manner in a talk.', 'Use it to help a client keep a relationship in view during a hard talk.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an upcoming conversation and plan each GIVE step. Role-play it and ask the client how the other person might feel. Aim for practice, not perfection.', '[{"id": "f0", "type": "textarea", "label": "The conversation I will have"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle"}, {"id": "f2", "type": "textarea", "label": "How I will show interest"}, {"id": "f3", "type": "textarea", "label": "How I will validate"}, {"id": "f4", "type": "textarea", "label": "How I will keep an easy manner"}]'::jsonb, array['GIVE', 'interpersonal effectiveness', 'validation', 'relationship issues']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('complaint-to-request-rewrite-sheet', 'Complaint to Request Rewrite Sheet', 'couples'::resource_kind, 'A sheet for turning a complaint into a specific, kind request.', 'Use it to help partners ask for what they need without blame.', array['Couples']::text[], '25 minutes', 'Each partner writes a recent complaint and rewrites it as "I feel, I need, would you" in one line. Role-play the delivery and the response. Keep the focus on one request at a time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint"}, {"id": "f1", "type": "textarea", "label": "Partner A: my request"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint"}, {"id": "f3", "type": "textarea", "label": "Partner B: my request"}, {"id": "f4", "type": "textarea", "label": "How the request felt to hear"}]'::jsonb, array['soft start-up', 'communication', 'needs', 'relationship issues']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('family-feelings-house-drawing', 'Family Feelings House Drawing', 'kids'::resource_kind, 'A drawing of a house with a room for each family member showing their feelings.', 'Use it to help a child show how they see their family.', array['Children']::text[], '25 minutes', 'The child draws a house, adds family members in rooms and chooses faces or colors for each. Ask what is in each room. Tell the parent to listen without fixing. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the house and rooms"}, {"id": "f1", "type": "textarea", "label": "How each person feels"}, {"id": "f2", "type": "textarea", "label": "Where I feel safest"}, {"id": "f3", "type": "textarea", "label": "What I wish for"}, {"id": "f4", "type": "textarea", "label": "Who I tell about big feelings"}]'::jsonb, array['family', 'feelings', 'drawing', 'relationship issues']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-sorting-game', 'Needs and Wants Sorting Game', 'game'::resource_kind, 'A game where players sort cards into needs and wants in relationships and discuss.', 'Use it to help a group tell needs from wants.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Cards list things like time alone and gifts. Players sort them into two piles and explain. Others may question once. Debrief on what moved piles and why.', '[{"id": "f0", "type": "textarea", "label": "A need I sorted"}, {"id": "f1", "type": "textarea", "label": "A want I sorted"}, {"id": "f2", "type": "textarea", "label": "What I learned from others"}, {"id": "f3", "type": "textarea", "label": "A need I want to ask for"}]'::jsonb, array['needs', 'boundaries', 'game', 'relationship issues']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('safety-and-support-map', 'Safety and Support Map', 'worksheet'::resource_kind, 'A map of safe people, safe places and next steps a client can reach for.', 'Use it to help a client build a present-day circle of safety and support.', array['Adults', 'Teens']::text[], '25 minutes', 'Focus on who and where is safe now. Do not ask for details of what happened. Include a trusted adult, a hotline and a safe place. For a minor, consider your reporting duties. Share 988 (call or text) if the client feels unsafe.', '[{"id": "f0", "type": "textarea", "label": "People I feel safe with"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "A trusted adult I can tell"}, {"id": "f3", "type": "textarea", "label": "What I can do if I feel unsafe"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) and other numbers I will keep"}]'::jsonb, array['safety', 'support', 'stabilizing', 'sexual abuse']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('self-blame-gentle-check-sheet', 'Self-Blame Gentle Check Sheet', 'cbt'::resource_kind, 'A sheet for looking at self-blame thoughts without retelling events.', 'Use it to help a client loosen blame that belongs elsewhere.', array['Adults', 'Teens']::text[], '25 minutes', 'Focus on the thought, not on the event: "What do I tell myself, and what would I tell a friend?" Never ask for details. Acknowledge that blame belongs to the person who caused harm. Stop if the client is overwhelmed.', '[{"id": "f0", "type": "textarea", "label": "A thought of blame I have"}, {"id": "f1", "type": "textarea", "label": "How much I believe it"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "Who holds responsibility"}, {"id": "f4", "type": "textarea", "label": "A kinder sentence I can try"}]'::jsonb, array['self-blame', 'shame', 'stabilizing', 'sexual abuse']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('body-anchors-and-values-page', 'Body Anchors and Values Page', 'act'::resource_kind, 'A page pairing gentle body anchors with something the client wants to do.', 'Use it to help a client feel present and move toward what they value.', array['Adults']::text[], '25 minutes', 'Offer anchors the client can choose or decline, such as feeling feet on the floor. Offer no touch or eye contact without consent. Ask about one valued action. Keep it brief and paced.', '[{"id": "f0", "type": "textarea", "label": "An anchor I choose"}, {"id": "f1", "type": "textarea", "label": "What I notice in the room"}, {"id": "f2", "type": "textarea", "label": "Something I value"}, {"id": "f3", "type": "textarea", "label": "A small action toward it"}, {"id": "f4", "type": "textarea", "label": "What I do if it feels like too much"}]'::jsonb, array['grounding', 'values', 'pacing', 'sexual abuse']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-safety-card', 'Distress Tolerance Safety Card', 'dbt'::resource_kind, 'A card of skills for surges of distress, kept in the client''s phone or pocket.', 'Use it to give a client calming and safe options in the moment.', array['Adults', 'Teens']::text[], '20 minutes', 'List skills the client picks, such as cold water, naming five things they can see and calling a friend. Rehearse. Include a plan if they feel unsafe, with 988 (call or text). Keep the card out of anyone''s hands the client does not choose.', '[{"id": "f0", "type": "textarea", "label": "Skills I will use first"}, {"id": "f1", "type": "textarea", "label": "What I see, hear and feel right now"}, {"id": "f2", "type": "textarea", "label": "Who I can call"}, {"id": "f3", "type": "textarea", "label": "What I do if I feel unsafe, including 988 (call or text)"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['distress tolerance', 'grounding', 'safety', 'sexual abuse']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('consent-and-pacing-conversation-guide', 'Consent and Pacing Conversation Guide', 'couples'::resource_kind, 'A guide for partners to talk about pacing, signals and consent in daily closeness.', 'Use it to help partners set signals and a pace the survivor leads.', array['Couples']::text[], '30 minutes', 'The partner who has experienced abuse sets the pace and chooses signals; the other listens. Do not ask for past details. Plan a stop word and a way to reconnect afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what pace feels okay"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I will respond to a stop"}, {"id": "f2", "type": "textarea", "label": "Our signals and stop word"}, {"id": "f3", "type": "textarea", "label": "How we reconnect after a pause"}, {"id": "f4", "type": "textarea", "label": "What we will talk about next time"}]'::jsonb, array['consent', 'pacing', 'safety', 'sexual abuse']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('calm-corner-design-craft', 'Calm Corner Design Craft', 'kids'::resource_kind, 'A craft where a child plans and decorates a calm corner at home.', 'Use it to help a child pick things that help them settle.', array['Children']::text[], '30 minutes', 'The child draws or builds a calm corner with items they choose, such as a pillow, a book and a glitter bottle. The parent offers it as a kind choice, not a punishment. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm corner"}, {"id": "f1", "type": "textarea", "label": "Things I will put in it"}, {"id": "f2", "type": "textarea", "label": "What I do there"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can help"}]'::jsonb, array['calming', 'craft', 'self-regulation', 'coping skills']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('coping-skill-relay-game', 'Coping Skill Relay Game', 'game'::resource_kind, 'A relay where teams act out a coping skill and the other team guesses it.', 'Use it to review coping skills in an active way.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Divide into teams. A member draws a skill card, acts it out without words and the team guesses it. Next member goes. Debrief on skills people want to add to their own lists.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted out"}, {"id": "f1", "type": "textarea", "label": "A skill I did not know"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['coping skills', 'skills', 'game']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-time-available-page', 'Coping Skills by Time Available Page', 'worksheet'::resource_kind, 'A page sorting skills into one minute, ten minutes and an hour.', 'Use it to help a client pick a skill that fits the time they have.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the list from skills the client already uses. Mark their favorites. Plan which one they will use at work, at home and at night. Review next time.', '[{"id": "f0", "type": "textarea", "label": "One-minute skills"}, {"id": "f1", "type": "textarea", "label": "Ten-minute skills"}, {"id": "f2", "type": "textarea", "label": "One-hour skills"}, {"id": "f3", "type": "textarea", "label": "My favorite and why"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this list"}]'::jsonb, array['coping skills', 'toolbox', 'planning']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('believable-coping-lines-card-builder', 'Believable Coping Lines Card Builder', 'cbt'::resource_kind, 'A page for writing short coping statements for hard moments.', 'Use it to give a client believable lines to say to themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'Brainstorm lines for a hard situation and test which feel believable. Avoid forced positivity. Put the best three on a card or phone note and practice them aloud.', '[{"id": "f0", "type": "textarea", "label": "A hard situation"}, {"id": "f1", "type": "textarea", "label": "What I tend to tell myself"}, {"id": "f2", "type": "textarea", "label": "A line that feels believable"}, {"id": "f3", "type": "textarea", "label": "Another that might help"}, {"id": "f4", "type": "textarea", "label": "Where I will keep the card"}]'::jsonb, array['coping thoughts', 'self-talk', 'coping skills']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('making-room-for-feelings-practice-page', 'Making Room for Feelings Practice Page', 'act'::resource_kind, 'A practice of allowing a feeling while doing a small valued action.', 'Use it to help a client use skills to move toward what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the feeling and where it is felt. Invite the client to make space for it with a slow breath and then take a valued action. Ask what changed, if anything, and what happened to the action.', '[{"id": "f0", "type": "textarea", "label": "The feeling I noticed"}, {"id": "f1", "type": "textarea", "label": "Where I feel it"}, {"id": "f2", "type": "textarea", "label": "What I did to make room"}, {"id": "f3", "type": "textarea", "label": "The valued action I took"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['acceptance', 'willingness', 'coping skills']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-facing-a-fear', 'Cope Ahead for Facing a Fear', 'dbt'::resource_kind, 'A page for planning skills to use before and during a planned fear exposure.', 'Use it to help a client rehearse skills before facing what they fear.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a step on the fear ladder. Plan what the client will do before, during and after, and rehearse the skill in imagination. Ask what could make the step feel safer to try.', '[{"id": "f0", "type": "textarea", "label": "The step I will try"}, {"id": "f1", "type": "textarea", "label": "What I expect to feel"}, {"id": "f2", "type": "textarea", "label": "Skills I will use before"}, {"id": "f3", "type": "textarea", "label": "Skills I will use during"}, {"id": "f4", "type": "textarea", "label": "How I will reward myself after"}]'::jsonb, array['cope ahead', 'exposure', 'fear ladder', 'phobias']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('supporter-coach-plan-for-partners', 'Supporter Coach Plan for Partners', 'couples'::resource_kind, 'A plan where the supporting partner learns how to coach without pushing.', 'Use it to help a partner cheer the other on in facing a fear.', array['Couples']::text[], '30 minutes', 'The person facing the fear says what helps and what does not. The partner writes short supportive lines and agrees not to push or rescue. Rehearse one step together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me and what does not"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can say and do"}, {"id": "f2", "type": "textarea", "label": "The step we will try"}, {"id": "f3", "type": "textarea", "label": "A signal to pause"}, {"id": "f4", "type": "textarea", "label": "How we will celebrate after"}]'::jsonb, array['support', 'exposure', 'accommodation', 'phobias']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('my-brave-meter-drawing', 'My Brave Meter Drawing', 'kids'::resource_kind, 'A drawing of a thermometer the child colors to show how scared they feel at each step.', 'Use it to help a child rate fear and see it change.', array['Children']::text[], '25 minutes', 'The child draws a thermometer with levels and picks colors. They rate fear before and after a small step. Tell the parent to cheer effort and avoid forcing. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your meter"}, {"id": "f1", "type": "textarea", "label": "How scared I am before"}, {"id": "f2", "type": "textarea", "label": "What I tried"}, {"id": "f3", "type": "textarea", "label": "How scared I am after"}, {"id": "f4", "type": "textarea", "label": "Who helped me"}]'::jsonb, array['fear thermometer', 'courage', 'drawing', 'phobias']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('climb-the-fear-steps-board-game', 'Climb the Fear Steps Board Game', 'game'::resource_kind, 'A board game where players move along a ladder of small steps toward a fear.', 'Use it to make graded steps feel playful and shared.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Draw a path with steps from easy to hard. Players roll to move and say how big the step feels. Rule: any step can be repeated. Debrief on what steps feel doable.', '[{"id": "f0", "type": "textarea", "label": "The step I landed on"}, {"id": "f1", "type": "textarea", "label": "How big it feels"}, {"id": "f2", "type": "textarea", "label": "What I could do next"}, {"id": "f3", "type": "textarea", "label": "Who can help me"}]'::jsonb, array['fear ladder', 'exposure', 'game', 'phobias']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('fear-prediction-and-outcome-page', 'Fear Prediction and Outcome Page', 'worksheet'::resource_kind, 'A page for writing what the client expects before facing a fear and what happened.', 'Use it to help a client compare feared and actual outcomes.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the prediction with a rating of how sure the client is. After the step, record what happened and what they learned. Repeat with the same or a harder step.', '[{"id": "f0", "type": "textarea", "label": "The fear step"}, {"id": "f1", "type": "textarea", "label": "What I think will happen"}, {"id": "f2", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['predictions', 'exposure', 'phobias']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('body-thought-check-sheet', 'Body Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for catching harsh thoughts about one''s body and writing a fairer view.', 'Use it to help a client loosen harsh body thoughts.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect a recent harsh thought, what triggered it and what it asked the client to do. Weigh evidence and write a fairer line focused on function and values rather than looks. Do not discuss numbers or measurements.', '[{"id": "f0", "type": "textarea", "label": "The harsh thought I had"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What it urged me to do"}, {"id": "f3", "type": "textarea", "label": "A fairer view"}, {"id": "f4", "type": "textarea", "label": "What I did instead"}]'::jsonb, array['automatic thoughts', 'self-criticism', 'body image']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('body-as-ally-values-page', 'Body as Ally Values Page', 'act'::resource_kind, 'A page about what the client wants their body to help them do.', 'Use it to help a client link their body to values rather than looks.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client wants to do in life that involves their body, such as hugging, dancing or traveling. Note the thoughts that get in the way and plan one small action.', '[{"id": "f0", "type": "textarea", "label": "Things I want my body to help me do"}, {"id": "f1", "type": "textarea", "label": "A value behind each one"}, {"id": "f2", "type": "textarea", "label": "Thoughts that get in the way"}, {"id": "f3", "type": "textarea", "label": "One small action this week"}, {"id": "f4", "type": "textarea", "label": "What I will do with the thoughts"}]'::jsonb, array['values', 'body awareness', 'committed action', 'body image']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('mirror-time-observe-and-describe-practice', 'Mirror Time Observe and Describe Practice', 'dbt'::resource_kind, 'A practice of describing what one sees and notices without judging.', 'Use it to help a client practice nonjudgment toward their reflection.', array['Adults', 'Teens']::text[], '20 minutes', 'The client describes neutral facts such as color of eyes or shape of a smile, then notices judgments and lets them be. Offer to start with a hand or another part they choose. Stop if distress rises.', '[{"id": "f0", "type": "textarea", "label": "What I observed"}, {"id": "f1", "type": "textarea", "label": "Where judgments showed up"}, {"id": "f2", "type": "textarea", "label": "How I labeled them"}, {"id": "f3", "type": "textarea", "label": "What I felt"}, {"id": "f4", "type": "textarea", "label": "What I will practice this week"}]'::jsonb, array['observe and describe', 'nonjudgmental stance', 'mindfulness', 'body image']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('appreciation-without-appearance-exchange', 'Appreciation Without Appearance Exchange', 'couples'::resource_kind, 'An exchange where partners appreciate each other for actions and character.', 'Use it to help partners build closeness beyond looks.', array['Couples']::text[], '25 minutes', 'Partners take turns naming things they appreciate that are not about appearance. Receivers say thanks and note how it lands. Discuss comments that help and those that do not.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate"}, {"id": "f2", "type": "textarea", "label": "What landed well"}, {"id": "f3", "type": "textarea", "label": "Comments that do not help me"}, {"id": "f4", "type": "textarea", "label": "What we will say more of"}]'::jsonb, array['appreciation', 'intimacy', 'body image']::text[], '2026-10-26T15:00:00+00:00'::timestamptz),
  ('feelings-beyond-the-mirror-drawing', 'Feelings Beyond the Mirror Drawing', 'kids'::resource_kind, 'A drawing of what makes the child special that cannot be seen in a mirror.', 'Use it to help a child value their qualities and actions.', array['Children']::text[], '25 minutes', 'The child draws a mirror and fills it with things like kindness, humor and trying hard. Tell the parent to praise actions and character. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your mirror"}, {"id": "f1", "type": "textarea", "label": "Things in me no one can see"}, {"id": "f2", "type": "textarea", "label": "Something I did that I am proud of"}, {"id": "f3", "type": "textarea", "label": "What my friends like about me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['strengths', 'art', 'self-worth', 'body image']::text[], '2026-10-26T15:00:00+00:00'::timestamptz)
